// Component layer — generated by line-matcher. Reusable presentation only.
export default function DealRow({ row, selected, onEdit }) {
  return (
    <tr data-selected={selected ? "true" : undefined}>
      <td>{row.name}</td>
      <td>{row.account}</td>
      <td>Arjun Rao</td>
      <td>Mia</td>
      <td>Mia</td>
      <td className="num">{row.value}</td>
      <td className="num">{row.margin}</td>
      <td>{row.closeOn}</td>
      <td>Proposal</td>
      <td className="actions">
        <button onClick={() => onEdit(row.id)}>Edit</button>
        <button>Forecast</button>
        <button className="danger">Delete</button>
      </td>
    </tr>
  );
}
